const output = $input.first().json.output;

// Find the beginning of "answer_LLM":
const startIdx = output.indexOf('"answer_LLM":');
if (startIdx === -1) {
  throw new Error('answer_LLM не найден');
}

// Find the first quote after "answer_LLM":
const contentStart = output.indexOf('"', startIdx + 13);

// Find the end of the object (last bracket)
const lastBrace = output.lastIndexOf('}');

// Take everything between the first quote and the last parenthesis
let content = output.substring(contentStart + 1, lastBrace);

// Remove the last quote if there is one
if (content.endsWith('"')) {
  content = content.slice(0, -1);
}

// Replace escaped characters
content = content.replace(/\\n/g, '\n');

return [
  {
    json: {
      answer_LLM: content.trim()
    }
  }
];

